CREATE TEMP TABLE native_results(name text,passed boolean,detail jsonb);
DO $test$
DECLARE tid uuid:=gen_random_uuid(); aid uuid:=gen_random_uuid(); iv jsonb;pk text;sha text;r jsonb;f jsonb;msg text;kind text;v uuid;
BEGIN
SELECT partition_key,immutable_input_versions||jsonb_build_object('rollback_fixture_id',tid) INTO STRICT pk,iv FROM population_top3000_202608_202609_v1.pipeline_partition WHERE family_id='N03';
UPDATE population_top3000_202608_202609_v1.pipeline_partition SET immutable_input_versions=iv WHERE family_id='N03' AND partition_key=pk;
sha:=encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.pipeline_validate_practical_v2(uuid,text)'::regprocedure),'UTF8')),'hex');
UPDATE population_top3000_202608_202609_v1.pipeline_adapter SET function_oid='population_top3000_202608_202609_v1.pipeline_validate_practical_v2(uuid,text)'::regprocedure,function_sha256=sha,enabled=true WHERE family_id='N03' AND stage='VALIDATE';
IF NOT FOUND THEN RAISE EXCEPTION 'FIXTURE_ADAPTER_ABSENT';END IF;
INSERT INTO population_top3000_202608_202609_v1.pipeline_task(task_id,operation_key,family_id,stage,partition_key,payload,input_versions,status,attempt_id,lease_until,owner_fence,stop_generation) VALUES(tid,'rollback-practical-v3:'||tid,'N03','VALIDATE',pk,'{}',iv,'LEASED',aid,clock_timestamp()+interval '3 minutes',3,1);
INSERT INTO population_top3000_202608_202609_v1.pipeline_attempt(attempt_id,task_id,execution_number,token_sha256,owner_fence,stop_generation,adapter_sha256) VALUES(aid,tid,1,encode(sha256(convert_to('rollback-only-token','UTF8')),'hex'),3,1,sha);
FOREACH kind IN ARRAY ARRAY['wrong_token','stop','stale_fence','expired_lease','adapter_hash','input_revision'] LOOP
 BEGIN
 CASE kind
 WHEN 'stop' THEN UPDATE population_top3000_202608_202609_v1.acquisition_control SET stopped=true;
 WHEN 'stale_fence' THEN UPDATE population_top3000_202608_202609_v1.pipeline_attempt SET owner_fence=2 WHERE attempt_id=aid;
 WHEN 'expired_lease' THEN UPDATE population_top3000_202608_202609_v1.pipeline_task SET lease_until=clock_timestamp()-interval '1second' WHERE task_id=tid;
 WHEN 'adapter_hash' THEN UPDATE population_top3000_202608_202609_v1.pipeline_attempt SET adapter_sha256='bad' WHERE attempt_id=aid;
 WHEN 'input_revision' THEN UPDATE population_top3000_202608_202609_v1.pipeline_task SET input_versions='{}' WHERE task_id=tid;
 ELSE NULL; END CASE;
 r:=population_top3000_202608_202609_v1.pipeline_validate_practical_v2(aid,CASE WHEN kind='wrong_token' THEN 'wrong' ELSE 'rollback-only-token' END);
 RAISE EXCEPTION 'TEST_UNEXPECTED_SUCCESS';
 EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS msg=MESSAGE_TEXT;
 INSERT INTO native_results VALUES(kind,msg=CASE kind WHEN 'wrong_token' THEN 'ATTEMPT_AUTH_FAILED' WHEN 'stop' THEN 'MISSION_HELD_OR_ADMISSION_EXPIRED' WHEN 'stale_fence' THEN 'STALE_OWNER_OR_STOP' WHEN 'expired_lease' THEN 'LEASE_LOST' WHEN 'adapter_hash' THEN 'ADAPTER_CODE_CHANGED' WHEN 'input_revision' THEN 'PARTITION_INPUT_REVISION_MISMATCH' END,jsonb_build_object('error',msg));
 END;
END LOOP;
r:=population_top3000_202608_202609_v1.pipeline_validate_practical_v2(aid,'rollback-only-token');
INSERT INTO native_results VALUES('actual_native_validation_preserves_nonacceptance',r->>'state'='COMPLETE' AND r->>'quality_result'<>'PASS',r);
f:=population_top3000_202608_202609_v1.pipeline_finish_v1(aid,'rollback-only-token',r);
INSERT INTO native_results VALUES('actual_finish_commit_and_automatic_repair',f->>'state'='COMPLETE' AND EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_commit WHERE task_id=tid) AND EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id=(f->>'successor_task_id')::uuid AND stage='REPAIR' AND input_versions=iv),f);
IF EXISTS(SELECT 1 FROM native_results WHERE passed IS DISTINCT FROM true) THEN RAISE EXCEPTION 'NATIVE_PROOF_FAILED:%',(SELECT jsonb_agg(to_jsonb(n)) FROM native_results n);END IF;
END $test$;
SELECT jsonb_build_object('tests',count(*),'passed',count(*) FILTER(WHERE passed),'cases',jsonb_agg(to_jsonb(n))) proof FROM native_results n;
